import json, re
with open('batches/batch_0003.json', encoding='utf-8') as f:
    data = json.load(f)

def hira_score(s):
    return len(re.findall(r'[ぁ-ん]', s))

def try_fix(s):
    if not s:
        return s
    # try utf-8 first
    try:
        u = s.encode('latin-1').decode('utf-8', errors='ignore')
    except Exception:
        u = ''
    u_score = hira_score(u)
    if u_score >= 3:
        return u
    # fallback euc_jp / cp932
    best = (s, hira_score(s))
    for enc in ['euc_jp','cp932','shift_jis']:
        try:
            fixed = s.encode('latin-1').decode(enc, errors='ignore')
        except Exception:
            continue
        sc = hira_score(fixed)
        if sc > best[1]:
            best = (fixed, sc)
    return best[0]

out = {}
for row in data:
    idx = row['idx']
    changed = False
    result = {}
    for field in ['title','desc','body']:
        val = row.get(field,'')
        fixed = try_fix(val)
        result[field] = fixed
        if fixed != val:
            changed = True
    if changed:
        out[idx] = result

